73	/// The single customer a scenario's policies belong to, together with the
74	/// standing they have earned with MHPCO: how long they have been in business
75	/// with the office, and how many contracts it has already written for them.
76	/// Every policy-wide modifier is measured against this standing.
77	#[derive(Clone, Copy, Debug)]
78	pub struct Customer {
79	    pub years_with_mhpco: u32,
80	    pub contracts_written: u32,
81	}
82	
83	impl Customer {
84	    pub fn with_years(years_with_mhpco: u32) -> Self {
85	        Self {
86	            years_with_mhpco,
87	            contracts_written: 0,
88	        }
89	    }
90	
91	    /// MHPCO counts a contract as a follow-up once it has already written the
92	    /// customer at least one: every contract after their first, not merely the
93	    /// second.
94	    fn on_a_follow_up_contract(&self) -> bool {
95	        self.contracts_written > 0
96	    }
97	
98	    /// The office enters the contract it has just written into the customer's
99	    /// standing, so the next quote is measured against the fuller history.
100	    fn record_contract_written(&mut self) {
101	        self.contracts_written += 1;
102	    }
103	}
104	
105	/// Every component is insured for the same sum, whatever its type.
106	const COMPONENT_INSURANCE_VALUE: u64 = 250;
107	
108	/// Every component is insured at the same uniform rate, whatever its type.
109	const COMPONENT_BASE_PREMIUM: u64 = 25;
110	
111	/// What the MHPCO price list records against one item type: the name the
112	/// office trades under for it, and the base premium it charges. The office
113	/// keeps the two together because an item type exists on the list precisely
114	/// by being priced on it -- a type it can name but not price, or price but
115	/// not name, is not something it insures.
116	struct PriceListEntry {
117	    name: &'static str,
118	    insurance_value: u64,
119	    base_premium: u64,
120	}
121	
122	impl ItemType {
123	    /// This type's entry on the MHPCO price list. The one place the office
124	    /// enumerates what it insures: every item type it knows is named and
125	    /// priced here, and nowhere else.
126	    const fn price_list_entry(self) -> PriceListEntry {
127	        let (name, insurance_value, base_premium) = match self {
128	            Self::Sword => ("sword", 1000, 100),
129	            Self::Amulet => ("amulet", 600, 60),
130	            Self::Staff => ("staff", 800, 80),
131	            Self::Potion => ("potion", 400, 40),
132	            Self::Rune => ("rune", COMPONENT_INSURANCE_VALUE, COMPONENT_BASE_PREMIUM),
133	            Self::Moonstone => ("moonstone", COMPONENT_INSURANCE_VALUE, COMPONENT_BASE_PREMIUM),
134	        };
135	        PriceListEntry {
136	            name,
137	            insurance_value,
138	            base_premium,
139	        }
140	    }
141	
142	    /// Every item type the price list carries, in the order the list states
143	    /// them.
144	    const PRICE_LIST: [Self; 6] = [
145	        Self::Sword,
146	        Self::Amulet,
147	        Self::Staff,
148	        Self::Potion,
149	        Self::Rune,
150	        Self::Moonstone,
151	    ];
152	
153	    /// Resolves the item type MHPCO knows by this name on its price list.
154	    pub fn named(name: &str) -> Result<Self, String> {
155	        Self::PRICE_LIST
156	            .into_iter()
157	            .find(|item_type| item_type.price_list_entry().name == name)
158	            .ok_or_else(|| format!("MHPCO does not insure items of type {name}"))
159	    }
160	}
161	
162	fn base_premium(item_type: ItemType) -> u64 {
163	    item_type.price_list_entry().base_premium
164	}
165	
166	/// What MHPCO insures one item of this type for, as its price list records.
167	/// This is the unmodified figure: no premium modifier and no block discount
168	/// bears on what an item is insured for.
169	fn insurance_value(item_type: ItemType) -> u64 {
170	    item_type.price_list_entry().insurance_value
171	}
172	
173	/// A building block is formed by exactly this many alike components:
174	/// neither fewer nor more qualify for the special block premium.
175	const BLOCK_COMPONENT_COUNT: usize = 3;
176	
177	/// The special base premium MHPCO offers for one building block.
178	const BLOCK_BASE_PREMIUM: u64 = 60;
179	
180	fn alike_group_base_premium(item_type: ItemType, count: usize) -> u64 {
181	    if count == BLOCK_COMPONENT_COUNT {
182	        return BLOCK_BASE_PREMIUM;
183	    }
184	    count as u64 * base_premium(item_type)
185	}
186	
187	/// Gathers the policy's items into groups of alike items, counting each group.
188	/// MHPCO counts two items as alike when they are of exactly the same item type
189	/// -- a rune and a moonstone are not alike, so they form no building block
190	/// together, and no other attribute of an item bears on the grouping.
191	fn alike_groups(items: &[Item]) -> Vec<(ItemType, usize)> {
192	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
193	    for item in items {
194	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
195	            Some((_, count)) => *count += 1,
196	            None => groups.push((item.item_type, 1)),
197	        }
198	    }
199	    groups
200	}
201	
202	fn policy_base_premium(items: &[Item]) -> u64 {
203	    alike_groups(items)
204	        .into_iter()
205	        .map(|(item_type, count)| alike_group_base_premium(item_type, count))
206	        .sum()
207	}
208	
209	/// A cursed item carries this share of its base premium as a risk surcharge.
210	const CURSE_SURCHARGE_RATE: u64 = 50;
211	
212	/// Every MHPCO modifier is quoted as a rate out of this whole.
213	const PERCENT: u64 = 100;
214	
215	/// An amount of money as MHPCO carries it through a calculation: an exact
216	/// fraction of a G, counted in hundredths. The office keeps every intermediate
217	/// amount in this form and rounds only once, when the final premium or payout
218	/// leaves the calculation -- and it rounds in its own favor, so a premium goes
219	/// up to the next whole G.
220	#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Default)]
221	struct Hundredths(u64);
222	
223	impl Hundredths {
224	    const PER_G: u64 = 100;
225	
226	    const ZERO: Self = Self(0);
227	
228	    fn from_whole_g(whole_g: u64) -> Self {
229	        Self(whole_g * Self::PER_G)
230	    }
231	
232	    /// A rate of this amount, quoted as a percentage of it. MHPCO states
233	    /// every modifier this way, and the share stays exact in hundredths:
234	    /// a rate that does not divide the amount evenly is carried as a
235	    /// fraction rather than rounded here.
236	    fn percentage(self, rate: u64) -> Self {
237	        Self(self.0 * rate / PERCENT)
238	    }
239	
240	    /// Rounds up to whole G, as MHPCO does with a premium.
241	    fn rounded_up_to_whole_g(self) -> u64 {
242	        self.0.div_ceil(Self::PER_G)
243	    }
244	
245	    /// Rounds down to whole G, as MHPCO does with a payout.
246	    fn rounded_down_to_whole_g(self) -> u64 {
247	        self.0 / Self::PER_G
248	    }
249	
250	    fn saturating_sub(self, other: Self) -> Self {
251	        Self(self.0.saturating_sub(other.0))
252	    }
253	}
254	
255	impl std::ops::Add for Hundredths {
256	    type Output = Self;
257	
258	    fn add(self, other: Self) -> Self {
259	        Self(self.0 + other.0)
260	    }
261	}
262	
263	impl std::iter::Sum for Hundredths {
264	    fn sum<I: Iterator<Item = Self>>(amounts: I) -> Self {
265	        amounts.fold(Self::ZERO, |running, amount| running + amount)
266	    }
267	}
268	
269	/// A net change MHPCO applies to an amount. Surcharges raise it and discounts
270	/// lower it, and because the discounts can outweigh the surcharges the net may
271	/// fall either way -- so it is kept signed until it meets the amount it adjusts.
272	#[derive(Clone, Copy, Debug)]
273	struct Adjustment(i64);
274	
275	impl Adjustment {
276	    fn raising(surcharge: Hundredths) -> Self {
277	        Self(surcharge.0 as i64)
278	    }
279	
280	    fn lowered_by(self, discount: Hundredths) -> Self {
281	        Self(self.0 - discount.0 as i64)
282	    }
283	}
284	
285	impl std::ops::Add<Adjustment> for Hundredths {
286	    type Output = Self;
287	
288	    fn add(self, adjustment: Adjustment) -> Self {
289	        Self(self.0.saturating_add_signed(adjustment.0))
290	    }
291	}
292	
293	/// A risk surcharge is always levied as a percentage of the affected item's
294	/// own base premium -- never of the policy total.
295	fn risk_surcharge(item: &Item, rate: u64) -> Hundredths {
296	    Hundredths::from_whole_g(base_premium(item.item_type)).percentage(rate)
297	}
298	
299	fn curse_surcharge(item: &Item) -> Hundredths {
300	    if item.cursed {
301	        return risk_surcharge(item, CURSE_SURCHARGE_RATE);
302	    }
303	    Hundredths::ZERO
304	}
305	
306	/// From this enchantment level on, an item counts as highly enchanted.
307	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
308	
309	/// A highly enchanted item carries this share of its base premium as a
310	/// risk surcharge.
311	const HIGH_ENCHANTMENT_SURCHARGE_RATE: u64 = 30;
312	
313	fn high_enchantment_surcharge(item: &Item) -> Hundredths {
314	    if item.enchantment >= HIGH_ENCHANTMENT_LEVEL {
315	        return risk_surcharge(item, HIGH_ENCHANTMENT_SURCHARGE_RATE);
316	    }
317	    Hundredths::ZERO
318	}
319	
320	/// The hazards MHPCO levies on a single item. An item that is both cursed and
321	/// highly enchanted carries both surcharges; they stack rather than compete.
322	fn item_risk_surcharge(item: &Item) -> Hundredths {
323	    curse_surcharge(item) + high_enchantment_surcharge(item)
324	}
325	
326	fn item_risk_surcharges(items: &[Item]) -> Hundredths {
327	    items.iter().map(item_risk_surcharge).sum()
328	}
329	
330	/// From this many years of business on, a customer counts as long-standing.
331	const LOYALTY_YEARS: u32 = 2;
332	
333	/// A long-standing customer receives this share of the policy base premium
334	/// as a discount.
335	const LOYALTY_DISCOUNT_RATE: u64 = 20;
336	
337	fn loyalty_discount(customer: &Customer, policy_base_premium: Hundredths) -> Hundredths {
338	    if customer.years_with_mhpco >= LOYALTY_YEARS {
339	        return policy_base_premium.percentage(LOYALTY_DISCOUNT_RATE);
340	    }
341	    Hundredths::ZERO
342	}
343	
344	/// Every quote is a first insurance of the items it covers, so MHPCO levies
345	/// this share of the policy base premium as an initial assessment surcharge.
346	const INITIAL_ASSESSMENT_RATE: u64 = 10;
347	
348	fn initial_assessment_surcharge(policy_base_premium: Hundredths) -> Hundredths {
349	    policy_base_premium.percentage(INITIAL_ASSESSMENT_RATE)
350	}
351	
352	/// Each contract after the customer's first earns this share of the policy
353	/// base premium as a discount.
354	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE: u64 = 15;
355	
356	fn follow_up_contract_discount(customer: &Customer, policy_base_premium: Hundredths) -> Hundredths {
357	    if customer.on_a_follow_up_contract() {
358	        return policy_base_premium.percentage(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
359	    }
360	    Hundredths::ZERO
361	}
362	
363	/// The modifiers MHPCO levies on the policy as a whole rather than on any one
364	/// item: they are measured against the policy base premium rather than any
365	/// item's. The discounts may outweigh the surcharge, so the catalogue nets out
366	/// to a single adjustment that can fall either way.
367	fn policy_wide_modifiers(customer: &Customer, policy_base_premium: Hundredths) -> Adjustment {
368	    Adjustment::raising(initial_assessment_surcharge(policy_base_premium))
369	        .lowered_by(loyalty_discount(customer, policy_base_premium))
370	        .lowered_by(follow_up_contract_discount(customer, policy_base_premium))
371	}
372	
373	const PROCESSING_FEE: u64 = 5;
374	
375	/// MHPCO keeps this much of every damage event to itself.
376	const DEDUCTIBLE_G: u64 = 100;
377	
378	/// From this enchantment level on, MHPCO reimburses only half the damage.
379	const HALVED_REIMBURSEMENT_LEVEL: u32 = 8;
380	
381	/// The share of the damage MHPCO reimburses on a highly enchanted item.
382	const HALVED_REIMBURSEMENT_RATE: u64 = 50;
383	
384	/// The share of the damage a clause reimburses when it reimburses in full.
385	const FULL_REIMBURSEMENT_RATE: u64 = PERCENT;
386	
387	/// A damage report matched to the insured item it refers to. MHPCO settles a
388	/// damage only against an item its policy actually covers, so the office
389	/// establishes the cover for every damage in the incident before it reimburses
390	/// any of them.
391	#[derive(Clone, Copy, Debug)]
392	struct CoveredDamage {
393	    item: Item,
394	    amount: u64,
395	}
396	
397	impl CoveredDamage {
398	    /// What MHPCO reimburses for this covered damage, before the policy cap.
399	    /// Two decisions in the order the policy wording puts them: the clause
400	    /// governing the damaged item first says what share of the damage is
401	    /// covered, and the deductible MHPCO keeps of every damage event is then
402	    /// taken off what that leaves.
403	    fn reimbursement(self) -> Hundredths {
404	        let covered = ReimbursementClause::governing(&self.item)
405	            .covers(Hundredths::from_whole_g(self.amount));
406	        covered.saturating_sub(Hundredths::from_whole_g(DEDUCTIBLE_G))
407	    }
408	}
409	
410	/// Reads the incident against the policy register, matching each damage report
411	/// to the insured item it refers to.
412	fn covered_damages(insured: &[Item], damages: &[Damage]) -> Vec<CoveredDamage> {
413	    damages
414	        .iter()
415	        .map(|damage| CoveredDamage {
416	            item: *insured
417	                .iter()
418	                .find(|item| item.item_type == damage.item_type)
419	                .expect("the damaged item is covered by the policy"),
420	            amount: damage.amount,
421	        })
422	        .collect()
423	}
424	
425	/// The clause of the MHPCO policy wording a damaged item falls under. Which
426	/// clause governs an item is a question about the item alone, settled before
427	/// any amount of money is named; what the clause then reimburses is stated
428	/// against the clause, not against the item.
429	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
430	enum ReimbursementClause {
431	    /// MHPCO reimburses only half the damage to a highly enchanted item.
432	    /// Stated first because it outranks the dragon-material clause: an item
433	    /// that falls under both is settled at the halved share.
434	    HighEnchantment,
435	    /// MHPCO reimburses damage to an item made of dragon material in full.
436	    DragonMaterial,
437	    /// Absent any special clause, MHPCO reimburses the damage in full.
438	    Standard,
439	}
440	
441	impl ReimbursementClause {
442	    /// The clause this damaged item falls under. Where an item answers to more
443	    /// than one special clause, the first one stated here governs it alone.
444	    fn governing(item: &Item) -> Self {
445	        if item.enchantment >= HALVED_REIMBURSEMENT_LEVEL {
446	            return Self::HighEnchantment;
447	        }
448	        if item.material == Material::Dragon {
449	            return Self::DragonMaterial;
450	        }
451	        Self::Standard
452	    }
453	
454	    /// What this clause covers of a damage it governs, before the deductible
455	    /// MHPCO withholds of every damage event is taken off. Each clause is
456	    /// stated as the share of the damage it reimburses.
457	    fn covers(self, damage: Hundredths) -> Hundredths {
458	        let reimbursed_share = match self {
459	            Self::HighEnchantment => HALVED_REIMBURSEMENT_RATE,
460	            Self::DragonMaterial | Self::Standard => FULL_REIMBURSEMENT_RATE,
461	        };
462	        damage.percentage(reimbursed_share)
463	    }
464	}
465	
466	/// What a policy insures its items for, all told.
467	fn insurance_sum(insured: &[Item]) -> u64 {
468	    insured
469	        .iter()
470	        .map(|item| insurance_value(item.item_type))
471	        .sum()
472	}
473	
474	/// MHPCO pays out at most this multiple of a policy's insurance sum.
475	const PAYOUT_CAP_MULTIPLE: u64 = 2;
476	
477	/// What a policy may still pay out. MHPCO opens it at twice the insurance
478	/// sum and never settles a claim for more than it holds, cutting a larger
479	/// reimbursement back to what is left.
480	#[derive(Clone, Copy, Debug)]
481	struct PolicyCap(u64);
482	
483	impl PolicyCap {
484	    /// The cap MHPCO opens on a freshly written policy.
485	    fn opened_on(insured: &[Item]) -> Self {
486	        Self(insurance_sum(insured) * PAYOUT_CAP_MULTIPLE)
487	    }
488	
489	    /// Settles a desired reimbursement against the cap: the office pays what
490	    /// the cap allows, and reports the cap left standing afterwards.
491	    fn settle(self, desired_payout: u64) -> Settlement {
492	        let payout = desired_payout.min(self.0);
493	        Settlement {
494	            payout,
495	            remaining_cap: self.0 - payout,
496	        }
497	    }
498	}
499	
500	/// What MHPCO owes for a whole incident, before the policy cap bears on it:
501	/// every covered damage the incident reports, reimbursed under the clause its
502	/// item falls under and less the deductible MHPCO keeps of each, added up.
503	fn incident_reimbursement(covered: &[CoveredDamage]) -> u64 {
504	    let reimbursement: Hundredths = covered
505	        .iter()
506	        .map(|damage| damage.reimbursement())
507	        .sum();
508	    reimbursement.rounded_down_to_whole_g()
509	}
510	
511	pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
512	    let policy_base_premium = Hundredths::from_whole_g(policy_base_premium(items));
513	    let premium = policy_base_premium
514	        + item_risk_surcharges(items)
515	        + policy_wide_modifiers(customer, policy_base_premium)
516	        + Hundredths::from_whole_g(PROCESSING_FEE);
517	    premium.rounded_up_to_whole_g()
518	}
519	
520	/// One damaged item and what the damage amounts to.
521	#[derive(Clone, Copy, Debug)]
522	pub struct Damage {
523	    pub item_type: ItemType,
524	    pub amount: u64,
525	}
526	
527	impl Damage {
528	    pub fn to(item_type: ItemType, amount: u64) -> Self {
529	        Self { item_type, amount }
530	    }
531	}
532	
533	/// What MHPCO settles on a claim.
534	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
535	pub struct Settlement {
536	    pub payout: u64,
537	    pub remaining_cap: u64,
538	}
539	
540	/// Identifies a policy the office has written.
541	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
542	pub struct PolicyRef(usize);
543	
544	/// The MHPCO office serving one customer through a scenario. It keeps the
545	/// customer's standing current as it works, so each operation sees the
546	/// history the office has accumulated for them so far.
547	pub struct ClaimOffice {
548	    customer: Customer,
549	    policies: Vec<Vec<Item>>,
550	}
551	
552	impl ClaimOffice {
553	    pub fn serving(customer: Customer) -> Self {
554	        Self {
555	            customer,
556	            policies: Vec::new(),
557	        }
558	    }
559	
560	    /// Writes a policy over the given items and returns a reference to it a
561	    /// later claim can be made against. The premium the office quotes for the
562	    /// policy is computed as for any quote; this entry point reports the
563	    /// policy rather than the premium.
564	    pub fn quote_policy(&mut self, items: &[Item]) -> PolicyRef {
565	        self.quote(items);
566	        self.enter_policy_in_the_register(items)
567	    }
568	
569	    /// The office enters the policy it has just written into its register, so
570	    /// a later claim can be settled against the items it covers.
571	    fn enter_policy_in_the_register(&mut self, items: &[Item]) -> PolicyRef {
572	        self.policies.push(items.to_vec());
573	        PolicyRef(self.policies.len() - 1)
574	    }
575	
576	    pub fn claim(&mut self, policy: PolicyRef, damages: &[Damage]) -> Option<Settlement> {
577	        let insured = &self.policies[policy.0];
578	        let covered = covered_damages(insured, damages);
579	        Some(PolicyCap::opened_on(insured).settle(incident_reimbursement(&covered)))
580	    }
581	
582	    pub fn quote(&mut self, items: &[Item]) -> u64 {
583	        let premium = quote(&self.customer, items);
584	        self.customer.record_contract_written();
585	        premium
586	    }
587	}
