603	    fn quotes_single_sword_at_its_base_premium() {
604	        assert_eq!(quote(&Customer::with_years(0), &[Item::new(ItemType::Sword)]), 115);
605	    }
606	
607	    #[test]
608	    fn quotes_single_amulet_at_its_base_premium() {
609	        assert_eq!(quote(&Customer::with_years(0), &[Item::new(ItemType::Amulet)]), 71);
610	    }
611	
